arguments.command:
sort -t',' -k2,2n <(cat <<EOF
${$(head -1 data/housing_dataset.csv)}`; tail -n +2 data/housing_dataset.csv}
EOF | head -50)} 2>/dev/null || (sort -t',' -k2,2n $(mktemp)) && echo "Sort check"; sort -t',' -k2,2n <(head -1 data/housing_dataset.csv; tail -n +2 data/housing_dataset.csv) > /tmp/sorted_areas.txt 2>&1 || true && cat /tmp/sorted_areas.txt | head -3
